function M.root()
 storage.tech_priests=storage.tech_priests or{};local r=storage.tech_priests[M.storage_key]or{version=M.version,enabled=true,read_only=true,input_output_proposals_integrated=true,port_collision_integrated=true,context_guard_integrated=true,fluid_item_policy_integrated=true,structured_scan_truth=true,stats={},recent={},entity_due={},reports={},cursor=0};storage.tech_priests[M.storage_key]=r;r.version=M.version
 if r.enabled==nil then r.enabled=true end;r.read_only=true;r.input_output_proposals_integrated=true;r.port_collision_integrated=true;r.context_guard_integrated=true;r.fluid_item_policy_integrated=true;r.structured_scan_truth=true;r.stats=r.stats or{};r.recent=r.recent or{};r.entity_due=r.entity_due or{};r.reports=r.reports or{};r.cursor=tonumber(r.cursor)or 0;return r
end
local function stat(k,n)local r=M.root();r.stats[k]=(tonumber(r.stats[k])or 0)+(tonumber(n)or 1)end
local function record(pair,action,detail)local r=M.root();r.recent[#r.recent+1]={tick=now(),station=safe(station_unit(pair)),action=tostring(action),detail=tostring(detail or"")};while#r.recent>160 do table.remove(r.recent,1)end;stat(action)end
local function fluidbox(e)local ok,b=pcall(function()return e.fluidbox end);return ok and b and b.valid and b or nil end
local function get_recipe(e)local ok,r=pcall(function()return e.get_recipe and e.get_recipe()end);return ok and r or nil end
local function recipe_fluids(recipe,field)
 local out={};local records;pcall(function()records=recipe and recipe[field]end);for _,rec in pairs(records or{})do local name=rec.name or rec[1];local kind=rec.type or(rec.name and"item");if kind=="fluid"and type(name)=="string"then out[#out+1]={name=name,amount=tonumber(rec.amount or rec.amount_min or rec[2])or 1,temperature=tonumber(rec.temperature)}end end;return out
end
local function segment_contents(box,index)local out={};if box and box.valid then pcall(function()out=box.get_fluid_segment_contents(index)or{}end)end;return type(out)=="table"and out or{}end
local function segment_id(box,index)local v;if box and box.valid then pcall(function()v=box.get_fluid_segment_id(index)end)end;return v end
local function capacity(box,index)local v=0;if box and box.valid then pcall(function()v=tonumber(box.get_capacity(index))or 0 end)end;return v end
local function prototype_record(box,index)local v;if box and box.valid then pcall(function()v=box.get_prototype(index)end)end;if type(v)=="table"and v.object_name==nil then for _,p in pairs(v)do if p then return p end end end;return v end
local function production_type(box,index)local p=prototype_record(box,index);local v;if p then pcall(function()v=p.production_type end)end;return v end
local function filter_name(box,index)
 local f;if box and box.valid then pcall(function()f=box.get_filter(index)end);if type(f)=="table"then f=f.name end;if not f then pcall(function()f=box.get_locked_fluid(index)end)end;if not f then local p=prototype_record(box,index);pcall(function()f=p and p.filter and p.filter.name end)end end;return type(f)=="string"and f~=""and f or nil
end
local function connection_records(box,index)
 local out={};local connections={};if box and box.valid then pcall(function()connections=box.get_pipe_connections(index)or{}end)end;for _,c in pairs(connections)do if type(c)=="table"then local owner;if c.target then pcall(function()owner=c.target.owner end)end;local p=c.target_position or c.position;out[#out+1]={position=p and{x=p.x,y=p.y}or nil,connected=c.target~=nil or valid(owner),target_owner=owner}end end;return out
end
local function free_targets(box,index)local out={};for _,c in ipairs(connection_records(box,index))do if c.position and not c.connected then out[#out+1]=c.position end end;return out end
local function requirement_for(index,box,inputs,outputs)
 local direction=production_type(box,index);local filter=filter_name(box,index);local contents=segment_contents(box,index);local function choose(list)
  if filter then for _,r in ipairs(list)do if r.name==filter then return r end end end
  for name,amount in pairs(contents)do if(tonumber(amount)or 0)>.001 then for _,r in ipairs(list)do if r.name==name then return r end end end end
  return#list==1 and list[1]or nil
 end
 if direction=="input"then return choose(inputs),"input"end;if direction=="output"then return choose(outputs),"output"end;if direction=="input-output"then local input=choose(inputs);return input or choose(outputs),input and"input"or"output"end
 local input=choose(inputs);if input then return input,"input"end;local output=choose(outputs);if output then return output,"output"end;return nil,direction or"unknown"
end
local function known_identity(record)local names={};if record.requirement and record.requirement.name then names[record.requirement.name]=true end;if record.filter then names[record.filter]=true end;for name,amount in pairs(record.contents or{})do if(tonumber(amount)or 0)>.001 then names[name]=true end end;return names end
local function port_records(e,inputs,outputs)
 local out={};local box=fluidbox(e);if not box then return out end;for index=1,#box do local req,direction=requirement_for(index,box,inputs or{},outputs or{});local connections=connection_records(box,index);local connected=false;for _,c in ipairs(connections)do if c.connected then connected=true break end end;out[#out+1]={index=index,direction=direction,requirement=req,filter=filter_name(box,index),contents=segment_contents(box,index),segment_id=segment_id(box,index),capacity=capacity(box,index),connections=connections,free_targets=free_targets(box,index),connected=connected}end;return out
end
local function touching_records(e,target,records)local out={};for _,rec in ipairs(records or{})do for _,c in ipairs(rec.connections or{})do if c.position and same_pos(c.position,target)then out[#out+1]=rec;break end end end;return out end
function M.validate_endpoint(e,index,target,fluid,records,allow_empty)
 if not(valid(e)and index and target and fluid)then return false,"invalid-endpoint"end;records=records or port_records(e,{},{});local touching=touching_records(e,target,records);if#touching==0 then return false,"target-not-on-fluidbox"end
 for _,rec in ipairs(touching)do local identities=known_identity(rec);local count=0;for name in pairs(identities)do count=count+1;if name~=fluid then return false,"fluidbox-"..rec.index..":different-fluid:"..name end end;if count==0 and not(allow_empty and(e.type=="pipe"or e.type=="pipe-to-ground"or e.type=="storage-tank"))then return false,"fluidbox-"..rec.index..":ambiguous-empty-unfiltered"end end
