end
local function service_radius(pair)local radius=tonumber(pair and pair.radius)or M.service_radius_floor;if valid_pair(pair)and type(_G.get_station_operating_radius)=="function"then local ok,v=pcall(_G.get_station_operating_radius,pair.station);if ok and tonumber(v)then radius=tonumber(v)end end;return math.max(8,math.min(math.max(radius,M.service_radius_floor),M.service_radius_cap))end
local function routed_find(surface,filters,category,key,ttl)local scanner=rawget(_G,"TechPriestsScanRouting0610")or package.loaded["scripts.core.scan_routing_0610"];if scanner and type(scanner.find_entities)=="function"then local entities=select(1,scanner.find_entities(surface,filters,{category=category,negative_key=key,negative_ttl=ttl or 300}));return entities or{}end;local ok,entities=pcall(function()return surface.find_entities_filtered(filters)end);return ok and entities or{}end
local function source_or_sink(pair,machine,fluid,direction)
 local radius=service_radius(pair);local p=pair.station.position;local entities=routed_find(machine.surface,{area={{p.x-radius,p.y-radius},{p.x+radius,p.y+radius}},force=machine.force,type=FLUID_TYPES,limit=M.max_sources},"standard-fluid-"..direction,"standard-fluid:"..direction..":"..safe(machine.surface.index)..":"..safe(machine.force.index)..":"..fluid,300);local best
 for _,e in pairs(entities)do if valid(e)and e~=machine then local records=port_records(e,{},{});for _,candidate in ipairs(records)do local identities=known_identity(candidate);local wrong=false;for name in pairs(identities)do if name~=fluid then wrong=true break end end;local amount=tonumber(candidate.contents and candidate.contents[fluid])or 0;local total=0;for _,n in pairs(candidate.contents or{})do total=total+(tonumber(n)or 0)end;local free=math.max(0,(tonumber(candidate.capacity)or 0)-total);local eligible=direction=="input"and amount>.001 or direction=="output"and not wrong and(free>.001 or next(identities)==nil)
   if eligible and not wrong then for _,target in ipairs(candidate.free_targets or{})do local ok=M.validate_endpoint(e,candidate.index,target,fluid,records,direction=="output");if ok then local score=dist_sq(e.position,machine.position)-(direction=="input"and math.min(amount,100000)*.001 or math.min(free,100000)*.001);if not best or score<best.score then best={entity=e,entity_name=e.name,entity_unit=e.unit_number,fluidbox_index=candidate.index,segment_id=candidate.segment_id,interfaces={target},amount=amount,free_capacity=free,score=score}end end end end
  end end end;return best
end
local function report_state(records)local missing,blocked={},{};for _,rec in ipairs(records)do if rec.requirement and rec.requirement.name then local amount=tonumber(rec.contents and rec.contents[rec.requirement.name])or 0;if rec.direction=="input"and not rec.connected and amount<=.001 then missing[#missing+1]=rec elseif rec.direction=="output"and not rec.connected and amount>.001 then blocked[#blocked+1]=rec end end end;return missing,blocked end
function M.inspect_machine(pair,machine,force)
 if not(valid_pair(pair)and valid(machine))then return nil,"invalid"end;local key=entity_key(machine);local r=M.root();if not force and key and(tonumber(r.entity_due[key])or 0)>now()then return r.reports[key],"cached"end;if key then r.entity_due[key]=now()+M.entity_cache_ticks end
 local recipe=get_recipe(machine);if not recipe then return nil,"no-recipe"end;local inputs=recipe_fluids(recipe,"ingredients");local outputs=recipe_fluids(recipe,"products");if#inputs==0 and#outputs==0 then return nil,"no-fluid-requirements"end;local records=port_records(machine,inputs,outputs);local missing,blocked=report_state(records);local report={version=M.version,tick=now(),read_only=true,machine=machine,machine_name=machine.name,machine_unit=machine.unit_number,station_unit=station_unit(pair),recipe_name=recipe.name,fluid_inputs=inputs,fluid_outputs=outputs,records=records,missing_inputs=missing,blocked_outputs=blocked,context_identity={surface_index=machine.surface.index,force_index=machine.force.index,machine_unit=machine.unit_number}};if key then r.reports[key]=report end;stat("machines-inspected");return report,"inspected"
end
local function proposals_for_report(pair,report)
 local inputs,outputs={},{};for _,rec in ipairs(report.missing_inputs or{})do local fluid=rec.requirement.name;local source=source_or_sink(pair,report.machine,fluid,"input");if source then local targets={};for _,target in ipairs(rec.free_targets or{})do local ok=M.validate_endpoint(report.machine,rec.index,target,fluid,report.records,false);if ok then targets[#targets+1]=target end end;if#targets>0 then inputs[#inputs+1]={version=M.version,tick=now(),expires_tick=now()+M.proposal_ttl,read_only=true,action="connect-fluid-input",direction="input",machine=report.machine,machine_name=report.machine_name,machine_unit=report.machine_unit,report_tick=report.tick,context_identity=report.context_identity,fluid=fluid,fluidbox_index=rec.index,connection_targets=targets,source=source,state="safe-source-found",port_collision_safe=true}end end end
 for _,rec in ipairs(report.blocked_outputs or{})do local fluid=rec.requirement.name;local sink=source_or_sink(pair,report.machine,fluid,"output");if sink then local targets={};for _,target in ipairs(rec.free_targets or{})do local ok=M.validate_endpoint(report.machine,rec.index,target,fluid,report.records,false);if ok then targets[#targets+1]=target end end;if#targets>0 then outputs[#outputs+1]={version=M.version,tick=now(),expires_tick=now()+M.proposal_ttl,read_only=true,action="connect-fluid-output",direction="output",machine=report.machine,machine_name=report.machine_name,machine_unit=report.machine_unit,report_tick=report.tick,context_identity=report.context_identity,fluid=fluid,fluidbox_index=rec.index,connection_targets=targets,sink=sink,state="safe-sink-found",port_collision_safe=true}end end end
 return inputs,outputs
end
function M.validate_proposal(pair,p)
 if not(valid_pair(pair)and type(p)=="table"and valid(p.machine)and p.context_identity and p.fluid and p.fluidbox_index)then return false,"invalid-proposal"end;if(tonumber(p.expires_tick)or 0)<now()then return false,"proposal-expired"end;if p.machine.surface~=pair.station.surface or p.machine.force~=pair.station.force then return false,"machine-context-mismatch"end;if p.context_identity.machine_unit and p.machine.unit_number~=p.context_identity.machine_unit then return false,"machine-unit-mismatch"end
 local report=M.inspect_machine(pair,p.machine,true);if not(report and report.context_identity.machine_unit==p.context_identity.machine_unit)then return false,"report-context-mismatch"end;local record;for _,rec in ipairs(report.records or{})do if rec.index==p.fluidbox_index and rec.requirement and rec.requirement.name==p.fluid then record=rec break end end;if not record then return false,"machine-port-no-longer-required"end
 local endpoint=p.direction=="input"and p.source or p.sink;if not(endpoint and valid(endpoint.entity)and endpoint.entity.surface==pair.station.surface and endpoint.entity.force==pair.station.force)then return false,"remote-endpoint-invalid"end;local machine_safe=false;for _,target in ipairs(p.connection_targets or{})do local ok=M.validate_endpoint(p.machine,p.fluidbox_index,target,p.fluid,report.records,false);if ok then machine_safe=true break end end;if not machine_safe then return false,"machine-port-unsafe"end
 local endpoint_records=port_records(endpoint.entity,{},{});local remote_safe=false;for _,target in ipairs(endpoint.interfaces or{})do local ok=M.validate_endpoint(endpoint.entity,endpoint.fluidbox_index,target,p.fluid,endpoint_records,p.direction=="output");if ok then remote_safe=true break end end;if not remote_safe then return false,"remote-port-unsafe"end;if p.direction=="input"then local amount=tonumber(segment_contents(fluidbox(endpoint.entity),endpoint.fluidbox_index)[p.fluid])or 0;if amount<=.001 then return false,"source-fluid-empty"end end;return true,"safe",report
end
function M.scan_pair(pair,force)
 if M.root().enabled==false or not valid_pair(pair)then return{processed=0,failed=not valid_pair(pair)and 1 or 0,detail="disabled-or-invalid"}end;if not force and now()<(tonumber(pair.fluid_network_scan_due_0689)or 0)then return{processed=0,acted=0,detail="cached"}end;pair.fluid_network_scan_due_0689=now()+M.scan_interval
 local radius=service_radius(pair);local p=pair.station.position;local machines=routed_find(pair.station.surface,{area={{p.x-radius,p.y-radius},{p.x+radius,p.y+radius}},force=pair.station.force,type=MACHINE_TYPES,limit=M.max_machines},"standard-fluid-machines","standard-fluid-machines:"..safe(pair.station.surface.index)..":"..safe(pair.station.force.index)..":"..safe(station_unit(pair)),180)
 local reports,inputs,outputs={},{},{};for _,machine in pairs(machines)do local report=M.inspect_machine(pair,machine,false);if report then reports[#reports+1]=report;local a,b=proposals_for_report(pair,report);for _,v in ipairs(a)do inputs[#inputs+1]=v end;for _,v in ipairs(b)do outputs[#outputs+1]=v end end end
 pair.machine_fluid_reports_0689=reports;pair.machine_fluid_network_0689=reports[1];pair.fluid_connection_proposals_0689=inputs;pair.fluid_output_sink_proposals_0694=outputs;record(pair,"pair-scan","machines="..#reports.." inputs="..#inputs.." outputs="..#outputs);return{processed=1,acted=0,waiting=#inputs+#outputs,detail="machines="..#reports}
end
local function patch_diagnostics()
 local d=rawget(_G,"TECH_PRIESTS_DIAGNOSTICS_BEHAVIOR_AUTHORITY_0468")or rawget(_G,"TechPriestsEmergencyDiagnostics0468");if not(d and type(d.pair_dump_lines)=="function")or d.fluid_network_doctrine_0689_wrapped then return false end;d.fluid_network_doctrine_0689_wrapped=true;local previous=d.pair_dump_lines;d.pair_dump_lines=function(...)local lines=previous(...);lines=type(lines)=="table"and lines or{};local r=M.root();lines[#lines+1]="PAIR-DUMP-0468 FLUID-NETWORK-0689 enabled="..safe(r.enabled).." read_only=true context_integrated=true collision_integrated=true inspected="..safe(r.stats["machines-inspected"]or 0);return lines end;return true
